css:
/* 固定幅なら path() が最短 */
.hero{clip-path:path('M0,72 C200,8 500,4 720,44 L720,300 C520,352 220,342 0,306 Z');overflow:hidden}
/* 可変幅は PNG/SVG マスク */
.hero img{-webkit-mask-image:url(tear-mask.png);mask-image:url(tear-mask.png);
          -webkit-mask-size:cover;mask-size:cover}
.hero .ghost{position:absolute;inset:0;background:#5f9c52;transform:translate(6px,10px);z-index:-1;
             mask-image:url(tear-mask.png);mask-size:cover}
